import math

def dist(x1, x2, y1, y2):
	return math.sqrt((x1 - x2) ** 2 + (y1 - y2) ** 2)

def calculate(c1, c2, l):
	radsum = c1[2] + c2[2]
	distc = dist(c1[0], c2[0], c1[1], c2[1])
	maxrad = max(c1[2], c2[2])
	minrad = min(c1[2], c2[2])
	if distc > radsum:
		mindist = distc - radsum
		maxdist = distc + radsum
	elif distc < maxrad - minrad:
		mindist = maxrad - minrad - distc
		maxdist = 2 * maxrad - mindist
	else:
		mindist = 0
		maxdist = radsum + distc
	return [mindist, maxdist]
(n, q) = [int(i) for i in input().split()]
circles = []
query = []
for j in range(n):
	circles.append([int(i) for i in input().split()])
for i in range(q):
	query.append(int(input()))
l = [0] * 1000001
for i in range(len(circles)):
	for j in range(i + 1, len(circles)):
		x = calculate(circles[i], circles[j], l)
		l[math.ceil(x[0])] += 1
		l[math.floor(x[1]) + 1] -= 1
for i in range(1, len(l)):
	l[i] = l[i] + l[i - 1]
for i in query:
	print(l[i])
